(function(){'use strict';var state={results:null,history:[]};var elements={};

function init(){elements={input:document.getElementById('hb-input'),indentSize:document.getElementById('hb-indent-size'),useTabs:document.getElementById('hb-use-tabs'),output:document.getElementById('hb-output'),opBadge:document.getElementById('hb-op-badge'),beautifyBtn:document.getElementById('beautify-btn'),minifyBtn:document.getElementById('minify-btn'),resetBtn:document.getElementById('reset-btn'),emptyState:document.getElementById('empty-state'),statusBadge:document.getElementById('status-badge'),resultArea:document.getElementById('result-area'),exportSection:document.getElementById('export-section'),exportCopy:document.getElementById('export-copy'),exportTxt:document.getElementById('export-txt'),exportJson:document.getElementById('export-json'),exportPrint:document.getElementById('export-print'),comparisonSection:document.getElementById('comparison-section'),comparisonSelect:document.getElementById('comparison-select'),comparisonTable:document.getElementById('comparison-table'),historySection:document.getElementById('history-section'),historyList:document.getElementById('history-list'),statLines:document.getElementById('stat-lines'),statTags:document.getElementById('stat-tags'),statAttrs:document.getElementById('stat-attrs'),statOriginal:document.getElementById('stat-original'),statBeautified:document.getElementById('stat-beautified'),statChange:document.getElementById('stat-change'),statDelta:document.getElementById('stat-delta')};
if(elements.beautifyBtn)elements.beautifyBtn.addEventListener('click',function(){process(false);});if(elements.minifyBtn)elements.minifyBtn.addEventListener('click',function(){process(true);});if(elements.resetBtn)elements.resetBtn.addEventListener('click',reset);if(elements.input)elements.input.addEventListener('input',onInput);
if(elements.exportCopy)elements.exportCopy.addEventListener('click',exportCopy);if(elements.exportTxt)elements.exportTxt.addEventListener('click',exportTxt);if(elements.exportJson)elements.exportJson.addEventListener('click',exportJson);if(elements.exportPrint)elements.exportPrint.addEventListener('click',exportPrint);if(elements.comparisonSelect)elements.comparisonSelect.addEventListener('change',onComparisonChange);showEmptyState();}

function onInput(){if(elements.input&&elements.input.value.trim()){updateStatus('ready','Ready');}else{updateStatus('','');}}

function updateStatus(type,text){if(elements.statusBadge){elements.statusBadge.className='status-badge'+(type?' '+type:'');elements.statusBadge.textContent=text;}}

function showEmptyState(){if(elements.emptyState)elements.emptyState.style.display='flex';if(elements.resultArea)elements.resultArea.style.display='none';}

function showResults(){if(elements.emptyState)elements.emptyState.style.display='none';if(elements.resultArea){elements.resultArea.style.display='block';elements.resultArea.classList.add('show');}}

function beautifyHTML(html,indentStr){var B={html:1,head:1,body:1,div:1,section:1,article:1,nav:1,aside:1,header:1,footer:1,main:1,p:1,h1:1,h2:1,h3:1,h4:1,h5:1,h6:1,blockquote:1,figcaption:1,figure:1,ul:1,ol:1,li:1,dl:1,dt:1,dd:1,form:1,fieldset:1,table:1,thead:1,tbody:1,tfoot:1,tr:1,td:1,th:1,caption:1,colgroup:1,col:1,details:1,summary:1,dialog:1,menu:1,hr:1};var P={script:1,style:1,pre:1,textarea:1};function isB(t){return B[t]===1}function isP(t){return P[t]===1}function fC(toks,idx){var d=1;for(var j=idx+1;j<toks.length;j++){if(toks[j].type==='open')d++;else if(toks[j].type==='close'){d--;if(d===0)return j;}}return -1}
function aI(toks,s,e){if(s>e)return false;for(var j=s;j<=e;j++){var t=toks[j];if(t.type==='text'){if(!t.value.replace(/^\s+|\s+$/g,''))continue}else if(t.type==='open'||t.type==='selfclose'){if(isB(t.tagName)||isP(t.tagName))return false}else if(t.type!=='close')return false}return true}
function rI(toks,s,e){var o='';for(var j=s;j<=e;j++){var t=toks[j];o+=t.type==='text'?t.value:t.value}return o.replace(/\s+/g,' ').replace(/^\s+|\s+$/g,'')}
var tokens=tokenize(html);var output='';var indent=0;var i=0;while(i<tokens.length){var tok=tokens[i];if(tok.type==='open'&&isP(tok.tagName)){output+=indentStr.repeat(indent)+tok.value+'\n';var ci=fC(tokens,i);if(ci!==-1){for(var j=i+1;j<ci;j++){var v=tokens[j].value.replace(/^\s+|\s+$/g,'');if(v)output+=v+'\n'}
output+=indentStr.repeat(indent)+tokens[ci].value+'\n';i=ci+1;continue}indent++;i++;continue}
function hT(toks,s,e){for(var j=s;j<=e;j++){var t=toks[j];if(t.type==='open'||t.type==='close'||t.type==='selfclose')return true}return false}
if(tok.type==='open'){var ci=fC(tokens,i);if(ci!==-1&&aI(tokens,i+1,ci-1)){var h=rI(tokens,i+1,ci-1);if(ci===i+1||!h){output+=indentStr.repeat(indent)+tok.value+tokens[ci].value+'\n'}else if(!hT(tokens,i+1,ci-1)&&(indentStr.length*indent+tok.value.length+h.length+tokens[ci].value.length)<=120){output+=indentStr.repeat(indent)+tok.value+h+tokens[ci].value+'\n'}else{output+=indentStr.repeat(indent)+tok.value+'\n';output+=indentStr.repeat(indent+1)+h+'\n';output+=indentStr.repeat(indent)+tokens[ci].value+'\n'}
i=ci+1;continue}}
if(tok.type==='close'){indent=Math.max(0,indent-1);output+=indentStr.repeat(indent)+tok.value+'\n'}else if(tok.type==='open'){output+=indentStr.repeat(indent)+tok.value+'\n';indent++}else if(tok.type==='selfclose'||tok.type==='comment'||tok.type==='doctype'){output+=indentStr.repeat(indent)+tok.value+'\n'}else if(tok.type==='text'){var txt=tok.value.replace(/^\s+|\s+$/g,'');if(!txt){i++;continue}
output+=indentStr.repeat(indent)+txt+'\n'}
i++}
return output.replace(/\n+$/,'')}
function tokenize(html){var tokens=[];var pos=0;while(pos<html.length){if(html[pos]==='<'){var next=html[pos+1];if(next!=='/'&&next!=='!'&&!(next>='a'&&next<='z')&&!(next>='A'&&next<='Z')){var end=html.indexOf('<',pos+1);if(end===-1)end=html.length;tokens.push({type:'text',value:html.slice(pos,end)});pos=end;continue;}
var r=html.slice(pos);if(r.slice(0,4)==='<!--'){var end=html.indexOf('-->',pos+4);if(end===-1)end=html.length;else end+=3;tokens.push({type:'comment',value:html.slice(pos,end)});pos=end;continue;}
if(r.slice(0,9).toLowerCase()==='<!doctype'||(r.slice(0,2)==='<!'&&r.length>2&&r[2].toLowerCase()>='a'&&r[2].toLowerCase()<='z')){var end=html.indexOf('>',pos+2);if(end===-1)end=html.length;else end+=1;tokens.push({type:'doctype',value:html.slice(pos,end)});pos=end;continue;}
if(html[pos+1]==='/'){var end=findTagEnd(html,pos+2);tokens.push({type:'close',value:html.slice(pos,end)});pos=end;continue;}
var end=findTagEnd(html,pos+1);var tagStr=html.slice(pos,end);var tagNameMatch=tagStr.match(/^<\s*([a-zA-Z_-][a-zA-Z0-9_-]*)/i);var tagName=tagNameMatch?tagNameMatch[1].toLowerCase():'';if((tagName==='script'||tagName==='style'||tagName==='pre'||tagName==='textarea')&&!tagStr.match(/\/\s*>$/)){var closeTag='</'+tagName+'>';var contentEnd=html.indexOf(closeTag,end);if(contentEnd===-1){tokens.push({type:'selfclose',tagName:tagName,value:tagStr});pos=end;}else{var content=html.slice(end,contentEnd);if(/^\s*$/.test(content)){tokens.push({type:'selfclose',tagName:tagName,value:tagStr+closeTag});}else{tokens.push({type:'open',tagName:tagName,value:tagStr});tokens.push({type:'text',value:content});tokens.push({type:'close',value:closeTag});}
pos=contentEnd+closeTag.length;}
continue;}
var isSelfClosing=!!tagStr.match(/\/\s*>$/)||['area','base','br','col','command','embed','hr','img','input','keygen','link','meta','param','source','track','wbr'].indexOf(tagName)!==-1;tokens.push({type:isSelfClosing?'selfclose':'open',tagName:tagName,value:tagStr});pos=end;}else{var end=html.indexOf('<',pos+1);if(end===-1)end=html.length;tokens.push({type:'text',value:html.slice(pos,end)});pos=end;}}
return tokens;}
function findTagEnd(html,start){var i=start;var inQuote=false;var quoteChar='';while(i<html.length){var ch=html[i];if(inQuote){if(ch===quoteChar)inQuote=false;}else if(ch==='"'||ch==="'"){inQuote=true;quoteChar=ch;}else if(ch==='>'){return i+1;}
i++;}
return html.length;}

function minifyHTML(html){return html.replace(/>\s+</g,'><').replace(/<!--[\s\S]*?-->/g,'').trim();}

function countTags(html){return(html.match(/<[a-zA-Z\/]/g)||[]).length;}

function countAttrs(html){var attrs=html.match(/\s+[a-zA-Z_-]+=/g);return attrs?attrs.length:0;}

function process(minify){var text=elements.input.value.trim();if(!text){showToast('Please enter HTML code','error');return;}
updateStatus('processing','Processing...');
var t0=performance.now();
setTimeout(function(){var indentSize=parseInt(elements.indentSize?elements.indentSize.value:'2')||2;var useTabs=elements.useTabs?elements.useTabs.checked:false;var indentStr=useTabs?'\t':new Array(indentSize+1).join(' ');
var output=minify?minifyHTML(text):beautifyHTML(text,indentStr);var t1=performance.now();
var lines=output.split('\n').length;var tags=countTags(output);var attrs=countAttrs(output);var originalSize=new Blob([text]).size;var beautifiedSize=new Blob([output]).size;var change=beautifiedSize-originalSize;
var opLabel=minify?'Minified':'Beautified';if(elements.opBadge)elements.opBadge.innerHTML='<span class="badge badge-'+opLabel.toLowerCase()+'">\u2713 '+opLabel+'</span>';
if(elements.output)elements.output.innerHTML='<pre class="hb-result"><code>'+escapeHtml(output)+'</code></pre>';
showResults();
var stats={operation:minify?'minify':'beautify',inputText:text.substring(0,80)+(text.length>80?'...':''),outputText:output,lines:lines,tags:tags,attrs:attrs,originalSize:originalSize,beautifiedSize:beautifiedSize,change:change,time:t1-t0};
state.results=stats;if(state.history.length>=5)state.history.shift();state.history.push(stats);
if(elements.statLines)elements.statLines.textContent=lines;if(elements.statTags)elements.statTags.textContent=tags;if(elements.statAttrs)elements.statAttrs.textContent=attrs;if(elements.statOriginal)elements.statOriginal.textContent=formatBytes(originalSize);if(elements.statBeautified)elements.statBeautified.textContent=formatBytes(beautifiedSize);if(elements.statChange)elements.statChange.textContent=(change>=0?'+':'')+formatBytes(change);if(elements.statDelta)elements.statDelta.textContent=(t1-t0)<1?'<1 ms':Math.round(t1-t0)+' ms';
updateStatus('done','Completed');
if(elements.exportSection)elements.exportSection.style.display='flex';
renderComparison();renderHistory();},100);}

function renderComparison(){if(!elements.comparisonSelect||!elements.comparisonTable)return;
var available=state.history.filter(function(item){return!state.results||item.inputText!==state.results.inputText;});
if(available.length===0||state.history.length<=1){if(elements.comparisonSection)elements.comparisonSection.style.display='none';return;}
if(elements.comparisonSection)elements.comparisonSection.style.display='block';
var html='<option value="">Select previous...</option>';
available.forEach(function(item,i){var idx=state.history.indexOf(item);
html+='<option value="'+idx+'">'+item.operation.charAt(0).toUpperCase()+item.operation.slice(1)+': '+item.inputText+' ('+item.lines+' lines)</option>';});
elements.comparisonSelect.innerHTML=html;}

function onComparisonChange(){var idx=parseInt(elements.comparisonSelect.value);
if(isNaN(idx)||!state.history[idx]||!state.results){elements.comparisonTable.innerHTML='';return;}
var prev=state.history[idx];var curr=state.results;
var metrics=[{label:'Operation',curr:curr.operation.charAt(0).toUpperCase()+curr.operation.slice(1),prev:prev.operation.charAt(0).toUpperCase()+prev.operation.slice(1)},{label:'Lines',curr:curr.lines,prev:prev.lines},{label:'Tags',curr:curr.tags,prev:prev.tags},{label:'Attributes',curr:curr.attrs,prev:prev.attrs},{label:'Output Size',curr:formatBytes(curr.beautifiedSize),prev:formatBytes(prev.beautifiedSize)},{label:'Original Size',curr:formatBytes(curr.originalSize),prev:formatBytes(prev.originalSize)},{label:'Time',curr:(curr.time<1?'<1 ms':Math.round(curr.time)+' ms'),prev:(prev.time<1?'<1 ms':Math.round(prev.time)+' ms')}];
var html='<table class="comparison-table"><thead><tr><th>Metric</th><th>Current</th><th>Previous</th><th>Change</th></tr></thead><tbody>';
metrics.forEach(function(m){var diff=typeof m.curr==='number'?m.curr-m.prev:0;
var arrow=diff>0?'<span class="comp-up">+'+diff+'</span>':diff<0?'<span class="comp-down">'+diff+'</span>':'<span class="comp-same">0</span>';
html+='<tr><td>'+m.label+'</td><td>'+m.curr+'</td><td>'+m.prev+'</td><td>'+arrow+'</td></tr>';});
html+='</tbody></table>';elements.comparisonTable.innerHTML=html;}

function renderHistory(){if(!elements.historyList)return;
if(state.history.length<=1){if(elements.historySection)elements.historySection.style.display='none';return;}
if(elements.historySection)elements.historySection.style.display='block';
var html='';for(var i=state.history.length-1;i>=0;i--){var item=state.history[i];
var active=state.results&&item.inputText===state.results.inputText?' style="border-color:var(--color-primary);background:rgba(37,99,235,0.05)"':'';
html+='<div class="history-item"'+active+'><div class="history-meta"><span class="history-time">'+item.operation.charAt(0).toUpperCase()+item.operation.slice(1)+'</span><span class="history-size">'+item.lines+' lines, '+formatBytes(item.beautifiedSize)+'</span></div><div class="history-lines">'+item.tags+' tags, '+item.attrs+' attrs</div></div>';}
elements.historyList.innerHTML=html;}

function exportCopy(){if(!state.results)return;var r=state.results;var text='HTML Beautifier Report\n=====================\n\nOperation: '+(r.operation==='beautify'?'Beautified':'Minified')+'\nLines: '+r.lines+'\nTags: '+r.tags+'\nAttributes: '+r.attrs+'\nOriginal Size: '+formatBytes(r.originalSize)+'\nOutput Size: '+formatBytes(r.beautifiedSize)+'\nChange: '+(r.change>=0?'+':'')+formatBytes(r.change)+'\nProcessing Time: '+(r.time<1?'<1 ms':Math.round(r.time)+' ms')+'\n\nOutput:\n'+r.outputText;
if(navigator.clipboard){navigator.clipboard.writeText(text.trim()).then(function(){showToast('Copied to clipboard!','success');});}else{fallbackCopy(text.trim());}}

function exportTxt(){if(!state.results)return;var r=state.results;var text='HTML Beautifier Report\n=====================\n\nOperation: '+(r.operation==='beautify'?'Beautified':'Minified')+'\nLines: '+r.lines+'\nTags: '+r.tags+'\nAttributes: '+r.attrs+'\nOriginal Size: '+formatBytes(r.originalSize)+'\nOutput Size: '+formatBytes(r.beautifiedSize)+'\nChange: '+(r.change>=0?'+':'')+formatBytes(r.change)+'\nProcessing Time: '+(r.time<1?'<1 ms':Math.round(r.time)+' ms')+'\n\nOutput:\n'+r.outputText;downloadFile('html-beautifier-report.txt',text,'text/plain');showToast('Downloaded TXT report','success');}

function exportJson(){if(!state.results)return;var obj={operation:state.results.operation,lines:state.results.lines,tags:state.results.tags,attributes:state.results.attrs,originalSize:state.results.originalSize,outputSize:state.results.beautifiedSize,change:state.results.change,processingTimeMs:Math.round(state.results.time),output:state.results.outputText,timestamp:new Date().toISOString()};var json=JSON.stringify(obj,null,2);downloadFile('html-beautifier-report.json',json,'application/json');showToast('Downloaded JSON report','success');}

function exportPrint(){window.print();}
function downloadFile(filename,content,mimeType){var blob=new Blob([content],{type:mimeType});var url=URL.createObjectURL(blob);var a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url);}
function fallbackCopy(text){var ta=document.createElement('textarea');ta.style.cssText='position:fixed;opacity:0';ta.value=text;document.body.appendChild(ta);ta.select();try{document.execCommand('copy');showToast('Copied!','success');}catch(e){showToast('Failed to copy','error');}document.body.removeChild(ta);}
function reset(){if(elements.input)elements.input.value='';if(elements.output)elements.output.innerHTML='';if(elements.opBadge)elements.opBadge.innerHTML='';state.results=null;state.history=[];if(elements.comparisonTable)elements.comparisonTable.innerHTML='';updateStatus('','');showEmptyState();if(elements.exportSection)elements.exportSection.style.display='none';if(elements.historySection)elements.historySection.style.display='none';if(elements.comparisonSection)elements.comparisonSection.style.display='none';}
function formatBytes(bytes){if(!bytes)return'0 B';if(bytes<1024)return bytes+' B';if(bytes<1048576)return(bytes/1024).toFixed(1)+' KB';return(bytes/1048576).toFixed(1)+' MB';}
function escapeHtml(str){if(typeof str!=='string')return'';return str.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function showToast(msg,type){var existing=document.querySelector('.toast');if(existing)existing.remove();var el=document.createElement('div');el.className='toast '+(type||'info');el.textContent=msg;document.body.appendChild(el);setTimeout(function(){el.classList.add('show');},10);setTimeout(function(){el.classList.remove('show');setTimeout(function(){el.remove();},300);},3000);}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}})();